'use strict';
window.TemplateTools=(()=>{
const variables={name:'Имя',company:'Организация',city:'Город',email:'Email',unsubscribe_url:'Ссылка отписки'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function personalize(source,values,html=false){return source.replace(/{{\s*([a-z_]+)\s*(?:\|([^{}]*))?}}/g,(token,key,fallback)=>{if(!Object.hasOwn(variables,key))return token;const value=key==='unsubscribe_url'?'https://example.com/unsubscribe-preview':String(values[key]||'').trim()||String(fallback||'').trim();return html?esc(value):value;});}
function mount(host,callbacks){
host.className='tpl-assistant';
host.innerHTML=`<details open><summary>Персонализация и подстановка данных</summary><p>Переменные: <code>{{name|клиент}}</code>, <code>{{company|вашей компании}}</code>, <code>{{city|вашем городе}}</code>, <code>{{email}}</code>. После | укажите запасной текст.</p>
<div class="tpl-tool-grid"><label>Переменная<select data-id="variable"></select></label><label>Запасной текст<input data-id="fallback" maxlength="150" placeholder="клиент"></label><label>Куда добавить<select data-id="insert-target"><option value="block">Выбранный блок</option><option value="subject">Тема</option><option value="preheader">Прехедер</option><option value="html">В конец HTML</option></select></label></div><button type="button" class="outline" data-id="insert">Добавить переменную в конец</button>
<h3>Пример получателя — только для предпросмотра</h3><div class="tpl-tool-grid" data-id="samples"></div><label><input type="checkbox" data-id="empty"> Проверить без данных получателя (запасные значения)</label><p>Данные примера не меняют базу клиентов. Ссылка отписки в предпросмотре демонстрационная.</p></details>
<details><summary>AI-помощник</summary><p data-id="ai-state">Проверка подключения…</p><div class="tpl-tool-grid"><label>Действие<select data-id="action"><option value="write">Написать текст</option><option value="improve">Улучшить текст</option><option value="shorten">Сократить</option><option value="business">Для бизнеса</option><option value="personal">Для физических лиц</option><option value="kazakh">На казахский</option><option value="russian">На русский</option></select></label><label>Применить к<select data-id="apply-target"><option value="block">Выбранному текстовому блоку</option><option value="new">Новому текстовому блоку</option><option value="subject">Теме письма</option><option value="preheader">Прехедеру</option></select></label></div>
<label>Задание AI<textarea data-id="instruction" maxlength="3000" placeholder="Опишите предложение, аудиторию и нужный тон. Укажите точные условия акции."></textarea></label><label>Исходный текст<textarea data-id="source" maxlength="8000"></textarea></label><button type="button" class="outline" data-id="take">Взять текст выбранного блока</button> <button type="button" class="outline" data-id="generate" disabled>Получить предложение AI</button>
<p>В OpenAI отправляются только задание и исходный текст из этих полей. База клиентов и данные примера не передаются. Лимит: 30 запросов в день на приложение. Ошибочные запросы тоже учитываются.</p><p role="status" data-id="ai-message"></p><label>Предложение AI — можно отредактировать<textarea data-id="result" maxlength="10000"></textarea></label><button type="button" class="outline" data-id="apply" disabled>Применить предложение</button></details>
<details open><summary>Проверки шаблона</summary><p>Переменные, ссылки, изображения, отписка, содержимое и размер HTML. Это не оценка вероятности попадания в спам.</p><button type="button" class="outline" data-id="check">Проверить шаблон</button><div data-id="findings" role="status"></div></details><p data-id="message" role="status"></p>`;
const $=id=>host.querySelector('[data-id="'+id+'"]');
for(const [key,name]of Object.entries(variables))$('variable').add(new Option(name,key));
const samples={name:'Алексей',company:'Пример компании',city:'Алматы',email:'client@example.com'};
for(const [key,val]of Object.entries(samples)){const label=document.createElement('label');label.textContent=variables[key];const input=document.createElement('input');input.value=val;input.maxLength=250;input.oninput=()=>{samples[key]=input.value;callbacks.preview();};label.append(input);$('samples').append(label);}
function values(){return $('empty').checked?{}:{...samples};}
$('empty').onchange=callbacks.preview;
$('insert').onclick=()=>{const key=$('variable').value;const token='{{'+key+($('fallback').value&&key!=='unsubscribe_url'?'|'+$('fallback').value.replace(/[{}]/g,''):'')+'}}';try{callbacks.apply($('insert-target').value,token,true);$('message').textContent='Переменная добавлена.';}catch(e){$('message').textContent=e.message;}};
$('take').onclick=()=>{$('source').value=callbacks.blockText();};
let suggestion=null,baseline='',request=0;
const signature=()=>JSON.stringify(callbacks.state());
function showSuggestion(){if(!suggestion)return;const target=$('apply-target').value;$('result').value=suggestion[target==='subject'?'subject':target==='preheader'?'preheader':'text'];}
$('apply-target').onchange=showSuggestion;
$('generate').onclick=async()=>{const seq=++request;baseline=signature();suggestion=null;$('apply').disabled=true;$('generate').disabled=true;$('result').value='';$('ai-message').textContent='AI готовит предложение…';try{const response=await api('/api/templates/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:$('action').value,instruction:$('instruction').value,source:$('source').value})});if(seq!==request)return;suggestion=response.suggestion;showSuggestion();$('apply').disabled=false;$('ai-message').textContent='Предложение готово. Проверьте факты и нажмите «Применить предложение».';}catch(e){$('ai-message').textContent=e.message;}finally{$('generate').disabled=false;}};
$('apply').onclick=()=>{try{if(signature()!==baseline)throw Error('Шаблон или выбранный блок изменился после запроса. Получите новое предложение AI.');callbacks.apply($('apply-target').value,$('result').value,false);baseline=signature();$('ai-message').textContent='Предложение применено. Изменения ещё не сохранены в БД.';$('apply').disabled=true;}catch(e){$('ai-message').textContent=e.message;}};
$('check').onclick=async()=>{const before=signature(),state=callbacks.state();$('check').disabled=true;$('findings').textContent='Проверка…';try{const r=await api('/api/templates/check',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subject:state.subject,preheader:state.preheader,html:state.html,values:values()})});$('findings').replaceChildren();const title=document.createElement('p');title.textContent=`Ошибок: ${r.errors}. Замечаний: ${r.warnings}.`;$('findings').append(title);for(const item of r.findings){const p=document.createElement('p');p.className=item.level==='error'?'tpl-check-error':'tpl-check-warning';p.textContent=(item.level==='error'?'Ошибка: ':'Замечание: ')+item.message;$('findings').append(p);}const note=document.createElement('p');note.textContent=r.note+(before!==signature()?' Шаблон изменился во время проверки — запустите её снова.':'');$('findings').append(note);}catch(e){$('findings').textContent=e.message;}finally{$('check').disabled=false;}};
api('/api/templates/ai').then(r=>{$('ai-state').textContent=r.configured?'AI подключён. Результат применяется только после вашего просмотра.':'AI не настроен. '+r.note;$('generate').disabled=!r.configured;}).catch(e=>{$('ai-state').textContent=e.message;});
TemplateMail.mount(host,{state:callbacks.state,values});
return {values};
}
return {personalize,mount};
})();
